import subprocess
import os
import shutil
from glob import glob

def task_func(src_folder, dst_folder):
    # Ensure source folder exists
    if not os.path.isdir(src_folder):
        return {
            'success': False,
            'message': f"Source folder does not exist: {src_folder}",
            'failed_files': []
        }

    # Create destination folder if it does not exist
    os.makedirs(dst_folder, exist_ok=True)

    # Collect all regular files (non-recursive)
    files = [
        f for f in glob(os.path.join(src_folder, '*'))
        if os.path.isfile(f)
    ]

    if not files:
        return {
            'success': True,
            'message': "No files to compress.",
            'failed_files': []
        }

    failed_files = []

    for filepath in files:
        filename = os.path.basename(filepath)
        compressed_path = filepath + '.gz'
        dest_path = os.path.join(dst_folder, filename + '.gz')

        # Skip if already compressed (ends with .gz)
        if filepath.endswith('.gz'):
            # Just move the file if not already in destination
            try:
                shutil.move(filepath, dest_path)
            except Exception:
                failed_files.append(filename)
            continue

        # Compress using gzip as a background-like subprocess
        # (we still wait for completion to know success/failure)
        try:
            # gzip -c input > output
            with open(compressed_path, 'wb') as out_f:
                proc = subprocess.Popen(
                    ['gzip', '-c', filepath],
                    stdout=out_f,
                    stderr=subprocess.PIPE
                )
                _, stderr = proc.communicate()

            if proc.returncode != 0:
                # Compression failed; remove partial output if any
                if os.path.exists(compressed_path):
                    os.remove(compressed_path)
                failed_files.append(filename)
                continue

            # Move compressed file to destination
            try:
                shutil.move(compressed_path, dest_path)
            except Exception:
                failed_files.append(filename)
                # Clean up local compressed file if move failed
                if os.path.exists(compressed_path):
                    os.remove(compressed_path)
                continue

        except Exception:
            # Any unexpected error during compression
            if os.path.exists(compressed_path):
                os.remove(compressed_path)
            failed_files.append(filename)
            continue

    if failed_files:
        return {
            'success': False,
            'message': "Some files failed to compress or move.",
            'failed_files': failed_files
        }

    return {
        'success': True,
        'message': "All files compressed and moved successfully.",
        'failed_files': []
    }
